import{_ as a,o as t,c as n,ak as i}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy team roles and work","description":"Confirmed by the user on October 12, 2026. Beta: November 3–6. Pre-final: November 21, 2026. Both fixed.","frontmatter":{"title":"Chainy team roles and work","description":"Confirmed by the user on October 12, 2026. Beta: November 3–6. Pre-final: November 21, 2026. Both fixed.","source":"docs/team-delegation.md","category":"Delivery & team","sourceUpdated":"2026-10-12T21:55:56+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/team-delegation.md","filePath":"content/docs/team-delegation.md"}'),o={name:"content/docs/team-delegation.md"};function s(r,e,c,l,d,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-team-roles-and-work">Chainy team roles and work<a class="header-anchor" href="#chainy-team-roles-and-work" aria-label="Link to this section">​</a></h1><p>Confirmed by the user on October 12, 2026. <strong>Beta: November 3–6. Pre-final: November 21, 2026. Both fixed.</strong></p><p>A lead owns the output. Support supplies a defined part. The reviewer checks the result. Use names in task fields; no invented GitHub accounts or teammate notification is implied.</p><h2 id="project-lead--sherwin-limosnero">Project Lead — Sherwin Limosnero<a class="header-anchor" href="#project-lead--sherwin-limosnero" aria-label="Link to this section">​</a></h2><p>Keep the scope, dates, people and school/site requirements aligned.</p><ul><li>CH-01: collect realistic hours, devices and school evidence requirements.</li><li>CH-24: confirm the fixed beta&#39;s contact, arrangements and required documents.</li><li>CH-17: coordinate the offline rehearsal and defense package.</li><li>CH-18/21: record panel actions and complete later handover.</li><li>Check blocked cards and integration readiness; do not declare a task complete without its output.</li></ul><p><strong>Handoff:</strong> a short decision/site record and a task plan the team can follow. <strong>Read:</strong> <a href="/Chainy-Docs/content/docs/project-baseline.html">baseline</a>, <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">Kanban/Gantt</a>, <a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">school evidence</a>.</p><h2 id="design-lead--sherwin-limosnero">Design Lead — Sherwin Limosnero<a class="header-anchor" href="#design-lead--sherwin-limosnero" aria-label="Link to this section">​</a></h2><p>This is Sherwin&#39;s second role, not another person&#39;s capacity.</p><ul><li>CH-02: define how Quiz, Wordle and BlockMatch teach a concept and how each starts, ends and retries.</li><li>CH-09: approve the content list, instructions and answer explanations with Sean.</li><li>Review Miguel&#39;s screen flow and Luis&#39;s art for clarity.</li><li>Keep new content/level quantity within the agreed schedule.</li></ul><p><strong>Handoff:</strong> one short rules/content sheet per mode, with examples of correct and incorrect play. <strong>Read:</strong> <a href="/Chainy-Docs/content/docs/game-design.html">GDD</a>, <a href="/Chainy-Docs/content/docs/learning-foundations.html">content guide</a>, <a href="/Chainy-Docs/content/docs/design/app-flow.html">flow</a>.</p><p>Sherwin also leads CH-08 Wordle and CH-11 teacher collection, with Christian reviewing technical work. These compete with project/design time. Confirm the coding split and hours before assuming all can proceed together.</p><h2 id="tech-lead--christian-jude-villaber">Tech Lead — Christian Jude Villaber<a class="header-anchor" href="#tech-lead--christian-jude-villaber" aria-label="Link to this section">​</a></h2><p>Own the working Unity architecture, builds, database and integration.</p><ul><li>CH-03/04: identify the working source/build and finish the agreed profile/save operations.</li><li>CH-05/06: connect exploration/dialogue and the first complete Quiz/save/reload loop.</li><li>CH-07: deliver BlockMatch; review Sherwin&#39;s Wordle and collection integration.</li><li>CH-13: combine the modes/content and freeze the beta candidate.</li><li>Review CH-14 device/recovery evidence; CH-20 owns the final release package.</li></ul><p><strong>Handoff:</strong> reproducible build, actual schema, tested behavior and known issues. <strong>Read:</strong> <a href="/Chainy-Docs/content/docs/technical-design.html">technical design</a>, <a href="/Chainy-Docs/content/docs/design/database-schema.html">database reference</a>, <a href="/Chainy-Docs/content/docs/hardware-validation.html">device checks</a>.</p><p>Christian owns shared scenes and database changes. Other contributors provide agreed components instead of editing these simultaneously. A nontechnical reviewer may check the user outcome but should not claim to have audited code.</p><h2 id="art-lead--luis-cabrido-iii">Art Lead — Luis Cabrido III<a class="header-anchor" href="#art-lead--luis-cabrido-iii" aria-label="Link to this section">​</a></h2><p>Deliver a small reusable visual set matching the approved Chainy style.</p><ul><li>CH-10: inventory the needed assets, make a representative sample and finish the agreed kit.</li><li>Support CH-05/09/13 with compact scene dressing, mode icons and instructional visuals.</li><li>Support CH-14 with readability checks on the actual phone.</li><li>Supply accurate figures/previews and license notes for manuscript/release handoff.</li></ul><p><strong>Handoff:</strong> editable assets, exports, import notes and a preview of intended use. <strong>Read:</strong> <a href="/Chainy-Docs/content/docs/design/design-brief.html">visual brief</a>, <a href="/Chainy-Docs/content/docs/game-design.html">GDD</a>, CH-10 in the <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html#ch-10">plan</a>.</p><h2 id="docs-lead--sean-matthew-narvaez">Docs Lead — Sean Matthew Narvaez<a class="header-anchor" href="#docs-lead--sean-matthew-narvaez" aria-label="Link to this section">​</a></h2><p>Keep the manuscript, instructional wording and evaluation evidence accurate.</p><ul><li>CH-22/23: revise Chapters I–III, source review, diagrams and evaluation instruments.</li><li>CH-12: record the approved protocol and evidence-handling procedure.</li><li>CH-15: coordinate actual beta evidence with Sherwin and the site.</li><li>CH-25/16: analyze real results, write Chapters IV–V and assemble the manuscript.</li><li>CH-19: complete remaining approved evaluation after pre-final feedback.</li><li>Support CH-02/06/07/08/09 with accurate questions, words, definitions and matching explanations.</li></ul><p><strong>Handoff:</strong> reviewed prose/content and an evidence index that distinguishes actual results from planned work. <strong>Read:</strong> <a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">official outline</a>, <a href="/Chainy-Docs/content/docs/manuscript-working-draft.html">working draft</a>, <a href="/Chainy-Docs/content/docs/qa-evaluation.html">evaluation</a>.</p><h2 id="ui-and-documentation-support--miguel-de-leon">UI and documentation support — Miguel De Leon<a class="header-anchor" href="#ui-and-documentation-support--miguel-de-leon" aria-label="Link to this section">​</a></h2><p>Miguel retains this role; he is not reassigned as Design Lead.</p><ul><li>CH-26: build readable profile, menu, mode, result, pause and save-error screens.</li><li>CH-14: execute and record device tests; Christian reviews technical conclusions.</li><li>Support profile/save/collection screens, integrated builds and beta operation.</li><li>Support Sean with figures, guide steps, formatting and appendices.</li></ul><p><strong>Handoff:</strong> screen flow/prefabs, reproducible test notes and current guide screenshots. <strong>Read:</strong> <a href="/Chainy-Docs/content/docs/design/app-flow.html">flow</a>, <a href="/Chainy-Docs/content/docs/design/design-brief.html">visual brief</a>, <a href="/Chainy-Docs/content/docs/user-guide.html">guide</a>, <a href="/Chainy-Docs/content/docs/qa-evaluation.html">QA checklist</a>.</p><h2 id="everyday-operation">Everyday operation<a class="header-anchor" href="#everyday-operation" aria-label="Link to this section">​</a></h2><p>Open your existing card. Check its prerequisite, agree the next small output and move it to In Progress when work starts. Post the artifact and actual check before requesting review. If blocked, state the missing input and who can supply it.</p><p>A useful handoff is five lines: <strong>what changed; artifact/build; checks performed; remaining issue; next owner</strong>. Use synthetic data in public/repository evidence.</p><p>The <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html#current-task-cards">26 task cards</a> define lead, support, reviewer, dates, dependencies and acceptance. They are the adopted publication plan; use the live team board for later task changes. Old hour allocations and assignments are <a href="/Chainy-Docs/content/docs/archive/pre-2026-10-12/docs/team-delegation.html">historical</a>.</p></div>',1)])])}const m=a(o,[["render",s]]);export{u as __pageData,m as default};
